using Xunit;

public sealed class PriceTests
{
    [Theory]
    [InlineData(100, 10, 90)]
    [InlineData(0, 10, 0)]
    public void DiscountReducesTheTotal(decimal price, decimal percent, decimal expected)
    {
        var actual = price * (1 - percent / 100);
        Assert.Equal(expected, actual);
    }
}

