using System.Diagnostics;

public sealed class OrderTelemetry(ILogger<OrderTelemetry> logger)
{
    public static readonly ActivitySource Source = new("Orders.Application");

    public async Task MeasureAsync(Guid orderId, Func<Task> operation)
    {
        using var activity = Source.StartActivity("order.process");
        using var scope = logger.BeginScope("Order {OrderId}", orderId);
        await operation();
        logger.LogInformation("Order processing completed");
    }
}
